<script setup lang="ts">
import {ref,computed} from 'vue'
import {useRoute} from 'vue-router'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import type {Row} from '../api/types'
import {useResource,money,number,nameOf,dateTime} from '../composables/useResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
import StatusTag from '../components/StatusTag.vue'
import EntityDialog from '../components/EntityDialog.vue'
import {projectFields} from './projectFields'
const route=useRoute(),auth=useAuth(),{data,loading,error,load}=useResource<{project:Row|null;metrics:Record<string,any>;costs:Row[];requests:Row[];orders:Row[];contracts:Row[];progress:Row[]}>(()=>`/projects/${route.params.id}`,{project:null,metrics:{},costs:[],requests:[],orders:[],contracts:[],progress:[]})
const tab=ref('overview'),dialog=ref(false),fields=computed(()=>projectFields(auth.catalog.users))
const metrics=[['request_amount','申请金额'],['order_amount','净采购订单额'],['receipt_amount','验收入库'],['material_cost','领料成本'],['paid_amount','净实付金额'],['purchase_return_amount','采购退货冲减'],['refund_amount','累计收到退款'],['refund_due_amount','待收供应商退款'],['other_cost','其他费用'],['actual_cost','实际成本'],['budget_usage','预算使用率'],['estimated_profit','预估利润']]
const isMobile=useMediaQuery()
</script>
<template><PageHeader :title="data.project?.name||'项目详情'" :subtitle="data.project?.code" back="/projects"><el-button @click="load" :loading="loading">刷新</el-button><el-button v-if="auth.can('project:write')&&data.project" type="primary" @click="dialog=true">编辑项目</el-button></PageHeader><ResourceState :error="error" :loading="loading" @retry="load"><template v-if="data.project"><div class="detail-banner"><div><StatusTag :value="data.project.status"/><h2>{{data.project.name}}</h2><p>{{data.project.location||'尚未填写项目地址'}}</p></div><div><span class="muted">项目预算（元）</span><strong>{{money(data.project.budget_amount)}}</strong><el-progress :percentage="Math.max(0,Math.min(100,Number(data.project.progress||0)))"/></div></div><el-alert v-if="Number(data.metrics.budget_usage)>100" title="项目实际成本已超过预算" :description="`预算使用率 ${number(data.metrics.budget_usage,2)}%，请核查材料领用与费用明细，及时调整成本控制计划。`" type="warning" show-icon :closable="false" style="margin:16px 0"/><div class="mini-metrics"><div v-for="[key,label] in metrics" :key="key"><span>{{label}}</span><b>{{key==='budget_usage'?`${number(data.metrics[key],2)}%`:money(data.metrics[key])}}</b></div></div><section class="panel"><el-tabs v-model="tab"><el-tab-pane label="项目概览" name="overview"><el-descriptions :column="isMobile?1:2" border><el-descriptions-item label="项目编号">{{data.project.code}}</el-descriptions-item><el-descriptions-item label="项目类型">{{data.project.type}}</el-descriptions-item><el-descriptions-item label="建设单位">{{data.project.owner}}</el-descriptions-item><el-descriptions-item label="施工单位">{{data.project.contractor}}</el-descriptions-item><el-descriptions-item label="项目经理">{{data.project.manager_name||nameOf(auth.catalog.users,data.project.manager_id)}}</el-descriptions-item><el-descriptions-item label="合同金额">¥ {{money(data.project.contract_amount)}}</el-descriptions-item><el-descriptions-item label="开工日期">{{data.project.start_date}}</el-descriptions-item><el-descriptions-item label="竣工日期">{{data.project.end_date}}</el-descriptions-item></el-descriptions><h3 class="section-title">进度记录</h3><el-empty v-if="!data.progress.length" description="暂无进度记录" :image-size="60"/><el-timeline><el-timeline-item v-for="item in data.progress" :key="item.id" :timestamp="dateTime(item.created_at)">{{number(item.progress)}}% · {{item.note||'项目进度更新'}}<span class="muted"> {{item.operator_name}}</span></el-timeline-item></el-timeline></el-tab-pane><el-tab-pane label="采购申请" name="requests"><DataTable :rows="data.requests" :columns="[{key:'code',label:'申请单号'},{key:'required_date',label:'需求日期'},{key:'total_amount',label:'申请金额',money:true},{key:'status',label:'状态',status:true}]"><template v-if="auth.can('request:read')&&auth.hasMenu('requests')" #actions="{row}"><el-button link type="primary" @click="$router.push(`/requests/${row.id}`)">查看申请</el-button></template></DataTable></el-tab-pane><el-tab-pane label="采购订单" name="orders"><DataTable :rows="data.orders" :columns="[{key:'code',label:'订单号'},{key:'supplier_name',label:'供应商'},{key:'total_amount',label:'订单金额',money:true},{key:'status',label:'状态',status:true}]"><template v-if="auth.can('order:read')&&auth.hasMenu('orders')" #actions="{row}"><el-button link type="primary" @click="$router.push(`/orders/${row.id}`)">查看订单</el-button></template></DataTable></el-tab-pane><el-tab-pane label="成本明细" name="costs"><DataTable :rows="data.costs" :columns="[{key:'category',label:'费用分类',status:true},{key:'description',label:'费用说明'},{key:'amount',label:'金额',money:true},{key:'incurred_date',label:'发生日期'}]"/></el-tab-pane><el-tab-pane label="关联合同" name="contracts"><DataTable :rows="data.contracts" :columns="[{key:'code',label:'合同编号'},{key:'name',label:'合同名称'},{key:'type',label:'类型',status:true},{key:'amount',label:'合同金额',money:true},{key:'status',label:'状态',status:true}]"/></el-tab-pane></el-tabs></section></template></ResourceState><EntityDialog v-model="dialog" title="编辑项目" endpoint="/projects" :record="data.project||undefined" :fields="fields" @saved="load"/></template>
